        startAnimation: async () => {
          await controls.start("fadeOut");
          controls.start("fadeIn");
          questionControls.start("show");
          scheduleHide();
        },
        stopAnimation: () => {
          cancelHide();
          controls.start("fadeIn");
          questionControls.start("hide");
        },
      };
    });

